return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'आपकी WordPress फ़ाइलों और डेटाबेस का आपके अपने स्टोरेज — Dropbox, Google Drive, Cloudflare R2, Amazon S3 या किसी भी S3-संगत बकेट में बैकअप लेता है — उन्हें एक ही बार में पुनर्स्थापित करता है, और अन्य बैकअप व माइग्रेशन प्लगइन्स द्वारा बनाए गए बैकअप आयात करता है।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'बैकअप','Get Pro: schedules, several storages, encryption'=>'Pro प्राप्त करें: शेड्यूल, एकाधिक स्टोरेज, एन्क्रिप्शन','Working…'=>'कार्य प्रगति पर है…','Finished'=>'पूर्ण हुआ','Failed'=>'विफल रहा','Cancelled'=>'रद्द किया गया','Cancel'=>'रद्द करें','Restore'=>'पुनर्स्थापित करें','Delete'=>'हटाएं','Delete this backup from your storage? This cannot be undone.'=>'क्या आप इस बैकअप को अपने स्टोरेज से हटाना चाहते हैं? यह क्रिया पूर्ववत नहीं की जा सकती।','No backups yet. Press “Back up now” to make the first one.'=>'अभी तक कोई बैकअप नहीं है। पहला बैकअप बनाने के लिए "अभी बैकअप लें" दबाएं।','Reading your storage…'=>'आपका स्टोरेज पढ़ा जा रहा है…','a complete backup, as opposed to an incremental oneFull backup'=>'पूर्ण बैकअप','a backup holding only what changed since an earlier oneIncremental backup'=>'इंक्रीमेंटल बैकअप','Encrypted'=>'एन्क्रिप्टेड','From another site'=>'किसी अन्य साइट से','Database'=>'डेटाबेस','Files'=>'फ़ाइलें','Uploading %1$s: %2$s%%'=>'%1$s अपलोड हो रहा है: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'खोली गई विंडो में Dropbox में साइन इन करें, फिर वह कोड चिपकाएँ जो Dropbox आपको दिखाता है:','Saved.'=>'सहेजा गया।','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'क्या इस गंतव्य को प्लगइन से हटाना है? इसमें संग्रहीत बैकअप हटाए नहीं जाएंगे।','Reload the page to see the restored site.'=>'पुनर्स्थापित साइट देखने के लिए पृष्ठ को पुनः लोड करें।','Storage'=>'स्टोरेज','Import & migrate'=>'आयात और माइग्रेट करें','Settings'=>'सेटिंग्स','Sections'=>'अनुभाग','Google Drive is connected.'=>'Google Drive कनेक्ट है।','Google Drive could not be connected.'=>'Google Drive कनेक्ट नहीं किया जा सका।','Details'=>'विवरण','Back up now'=>'अभी बैकअप लें','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'बैकअप आपके अपने स्टोरेज में जाते हैं, इस सर्वर पर नहीं। पहले <a href="%s">अपना स्टोरेज कनेक्ट करें</a>।','What to back up'=>'क्या बैकअप लेना है','Files and database'=>'फ़ाइलें और डेटाबेस','Database only'=>'केवल डेटाबेस','Files only'=>'केवल फ़ाइलें','Note (optional)'=>'नोट (वैकल्पिक)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'अगला भाग बनने से पहले प्रत्येक भाग आपके स्टोरेज में अपलोड कर दिया जाता है और इस सर्वर से हटा दिया जाता है, ताकि बैकअप आपकी होस्टिंग पर कभी जगह न ले।','Your backups'=>'आपके बैकअप','Refresh'=>'रीफ़्रेश करें','Restore this backup'=>'यह बैकअप पुनर्स्थापित करें','Passphrase'=>'पासफ़्रेज़','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'मैं समझता हूँ कि यह इस साइट की फ़ाइलों और डेटाबेस को बैकअप से बदल देता है। जो फ़ाइलें बैकअप में नहीं हैं, उन्हें रखा जाता है।','Recent activity'=>'हाल की गतिविधि','Backup'=>'बैकअप','Restore / import'=>'पुनर्स्थापित करें / आयात करें','Running'=>'चल रहा है','Your storage'=>'आपका स्टोरेज' . "\0" . 'आपके स्टोरेज गंतव्य','No storage yet. Choose where your backups go below.'=>'अभी कोई स्टोरेज नहीं है। नीचे चुनें कि आपके बैकअप कहाँ जाएँ।','Ready'=>'तैयार','Not connected'=>'कनेक्ट नहीं है','Connect'=>'कनेक्ट करें','Test'=>'परीक्षण','Edit'=>'संपादित करें','Remove'=>'हटाएं','Add storage'=>'स्टोरेज जोड़ें','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'बैकअप एक संग्रहण गंतव्य पर जाते हैं। किसी अन्य का उपयोग करने के लिए, ऊपर वाले को संपादित करें या हटाएं।','Kind of storage'=>'स्टोरेज का प्रकार','Name (for you)'=>'नाम (आपके लिए)','Provider'=>'प्रदाता','Cloudflare account id'=>'Cloudflare खाता आईडी','Endpoint address'=>'एंडपॉइंट पता','Region'=>'क्षेत्र','Bucket'=>'बकेट','Access key id'=>'एक्सेस कुंजी आईडी','Secret access key'=>'गुप्त एक्सेस कुंजी','Leave empty to keep the saved key'=>'सहेजी गई कुंजी रखने के लिए खाली छोड़ें','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2 के लिए: Cloudflare डैशबोर्ड में R2 खोलें, एक बकेट बनाएं, फिर “Manage R2 API tokens” → उस बकेट के लिए Object Read & Write के साथ एक टोकन बनाएं, और access key id तथा secret को यहाँ कॉपी करें।','Dropbox app key'=>'Dropbox ऐप कुंजी','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'dropbox.com/developers/apps पर files.content.read, files.content.write और files.metadata.read अनुमतियों के साथ एक ऐप बनाएं (Scoped access, App folder), और इसकी App key यहाँ कॉपी करें। सहेजें, फिर Connect दबाएं।','OAuth client id'=>'OAuth क्लाइंट आईडी','OAuth client secret'=>'OAuth क्लाइंट सीक्रेट','Leave empty to keep the saved secret'=>'सहेजे गए सीक्रेट को बनाए रखने के लिए खाली छोड़ें','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Google Cloud Console में, Google Drive API सक्षम करें, फिर इस पते को अधिकृत रीडायरेक्ट URI के रूप में उपयोग करके "Web application" प्रकार का एक OAuth क्लाइंट बनाएं:','Save, then press Connect. The plugin only sees the files it creates.'=>'सहेजें, फिर कनेक्ट करें दबाएं। प्लगइन केवल वही फ़ाइलें देखता है जो वह बनाता है।','Folder inside the storage (optional)'=>'स्टोरेज के अंदर फ़ोल्डर (वैकल्पिक)','Save storage'=>'स्टोरेज बचाएं','Import a backup from another plugin or host'=>'किसी अन्य प्लगइन या होस्ट से बैकअप आयात करें','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate द्वारा बनाए गए बैकअप से या किसी WordPress साइट के उसके .sql डंप वाले zip/tar संग्रह से साइट लाएं। सामग्री wp-content में जाती है और डेटाबेस इस साइट के डेटाबेस को बदल देता है; पते स्वचालित रूप से इस साइट के पते में बदल जाते हैं।','Upload from your computer'=>'अपने कंप्यूटर से अपलोड करें','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'बैकअप की प्रत्येक फ़ाइल को एक साथ चुनें (UpdraftPlus कई फ़ाइलें बनाता है)। बड़ी फ़ाइलें छोटे टुकड़ों में भेजी जाती हैं, इसलिए आपके होस्ट की अपलोड सीमा लागू नहीं होती है।','Or from links (Google Drive, Dropbox or any download address)'=>'या लिंक से (Google Drive, Dropbox या कोई भी डाउनलोड पता)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'प्रति पंक्ति एक लिंक। Google Drive और Dropbox के लिए, फ़ाइल को "लिंक वाले किसी भी व्यक्ति" के साथ साझा करें और वह लिंक चिपकाएँ; बाद में साझाकरण को फिर से बंद कर दें।','Or a file already on this server'=>'या इस सर्वर पर पहले से मौजूद कोई फ़ाइल','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'FTP या अपने होस्ट के फ़ाइल प्रबंधक के माध्यम से संग्रहों को %s में अपलोड करें और इस पृष्ठ को पुनः लोड करें।','Or a deploy code from another site'=>'या किसी अन्य साइट से डिप्लॉय कोड','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'यदि किसी अन्य साइट ने आपको Zinn® Backups डिप्लॉय कोड दिया है, तो उसकी स्टोरेज कुंजियाँ साझा किए बिना उस बैकअप को इस साइट पर कॉपी करने के लिए उसे यहाँ पेस्ट करें। एक कोड कुछ घंटों के लिए काम करता है; इसे पासवर्ड की तरह मानें।','Passphrase (only if that backup is encrypted)'=>'पासफ़्रेज़ (केवल तभी जब वह बैकअप एन्क्रिप्टेड हो)','Import'=>'आयात करें','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'मैं समझता हूँ कि आयात इस साइट की सामग्री और डेटाबेस को बदल देता है। इसके बाद, आयात की गई साइट के खाते से साइन इन करें।','Moving to Zinn® hosting?'=>'Zinn® होस्टिंग पर आ रहे हैं?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® आपके पुराने होस्ट से आपकी साइट को आपके लिए स्थानांतरित कर सकता है। यदि आपका पुराना होस्ट आपको FTP, SSH या नियंत्रण-पैनल एक्सेस प्रदान नहीं करता है, तो पुरानी साइट पर Zinn® Migrate स्थापित करें; यह एक संग्रह बनाता है जिसे आप यहाँ आयात कर सकते हैं या Zinn® को सौंप सकते हैं।','What goes into a backup'=>'बैकअप में क्या शामिल होता है','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'WordPress की अपनी फ़ाइलें (wp-admin, wp-includes) शामिल करें। आमतौर पर आवश्यकता नहीं होती: WordPress को हमेशा फिर से इंस्टॉल किया जा सकता है।','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'इन फ़ोल्डरों या फ़ाइलों को भी छोड़ दें (प्रति पंक्ति एक, WordPress फ़ोल्डर के सापेक्ष)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'हमेशा बाहर रखा जाता है: कैश, अपडेट स्क्रैच स्पेस, और अन्य बैकअप प्लगइन्स के अपने संग्रह फ़ोल्डर:','Size of each part (MB)'=>'प्रत्येक भाग का आकार (MB)','Save settings'=>'सेटिंग्स सहेजें','A backup part could not be opened for writing. Check that wp-content has free space.'=>'बैकअप का एक हिस्सा लिखने के लिए खोला नहीं जा सका। जाँच करें कि wp-content में खाली जगह है।','A backup part could not be written. Check that wp-content has free space.'=>'बैकअप का एक हिस्सा लिखा नहीं जा सका। कृपया जांचें कि wp-content में खाली जगह उपलब्ध है।','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'पहले Storage टैब पर कोई स्टोरेज गंतव्य कनेक्ट करें: बैकअप आपके अपने स्टोरेज में रखे जाते हैं, इस सर्वर पर नहीं।','Multisite networks are not supported yet.'=>'मल्टीसाइट नेटवर्क अभी समर्थित नहीं हैं।','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'इस सर्वर के PHP में ZipArchive एक्सटेंशन नहीं है। अपने होस्ट से इसे सक्षम करने के लिए कहें।','Starting'=>'शुरू हो रहा है','Listing files'=>'फ़ाइलों की सूची बनाई जा रही है','Backing up the database'=>'डेटाबेस का बैकअप लिया जा रहा है','Packing files'=>'फ़ाइलें पैक की जा रही हैं','Uploading to your storage'=>'आपके स्टोरेज में अपलोड हो रहा है','Finishing'=>'समाप्त किया जा रहा है','The backup reached an unknown stage.'=>'बैकअप अज्ञात चरण पर पहुँच गया।','Backup %s started.'=>'%s का बैकअप प्रारंभ हो गया।','Found %1$s files (%2$s).'=>'%1$s फ़ाइलें मिलीं (%2$s)।','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'डेटाबेस: %1$d तालिकाएं, %2$s पंक्तियां, %3$s संपीड़ित।','Backup complete: %1$s stored in %2$d destination.'=>'बैकअप पूर्ण: %1$s को %2$d गंतव्य में सहेजा गया।' . "\0" . 'बैकअप पूर्ण: %1$s को %2$d गंतव्यों में संग्रहीत किया गया।','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'पहले से अपलोड किए गए कुछ हिस्सों को आपके स्टोरेज से हटाया नहीं जा सका; वे एक अपूर्ण बैकअप फ़ोल्डर में हैं और उन्हें पुनर्स्थापना के लिए कभी पेश नहीं किया जाता है।','A storage destination was removed while the backup was running.'=>'बैकअप चलने के दौरान एक संग्रहण गंतव्य हटा दिया गया था।','That is not a backup folder.'=>'वह बैकअप फ़ोल्डर नहीं है।','That storage destination is no longer saved on this site.'=>'वह संग्रहण गंतव्य अब इस साइट पर सहेजा नहीं गया है।','Later incremental backups are built on this one. Delete those first.'=>'बाद के वृद्धिशील बैकअप इस पर आधारित हैं। पहले उन्हें हटाएं।','This file is not an encrypted Zinn® Backups file.'=>'यह फ़ाइल एन्क्रिप्ट की गई Zinn® Backups फ़ाइल नहीं है।','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'बैकअप को डिक्रिप्ट नहीं किया जा सका: पासफ़्रेज़ गलत है या फ़ाइल क्षतिग्रस्त है।','The encrypted backup file is incomplete.'=>'एन्क्रिप्ट की गई बैकअप फ़ाइल अधूरी है।','The database file could not be written. Check that wp-content has free space.'=>'डेटाबेस फ़ाइल नहीं लिखी जा सकी। जाँचें कि wp-content में खाली जगह है या नहीं।','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'यह डिप्लॉय कोड नहीं है। डिप्लॉय कोड zbdeploy1 से शुरू होता है।','That deploy code is damaged. Copy it again from the other site.'=>'वह डिप्लॉय कोड क्षतिग्रस्त है। इसे दूसरी साइट से पुनः कॉपी करें।','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'डिप्लॉय कोड की समय सीमा समाप्त हो गई है या उसका बैकअप हटा दिया गया है। दूसरी साइट पर एक नया कोड बनाएं।','That deploy code does not point at a Zinn® Backups backup.'=>'वह डिप्लॉय कोड Zinn® Backups बैकअप की ओर इंगित नहीं करता है।','The deploy code has expired. Make a new code on the other site.'=>'डिप्लॉय कोड की समय सीमा समाप्त हो गई है। दूसरी साइट पर एक नया कोड बनाएं।','The server stopped honouring partial downloads. Start the import again.'=>'सर्वर ने आंशिक डाउनलोड स्वीकार करना बंद कर दिया है। कृपया आयात फिर से शुरू करें।','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'लिंक ने फ़ाइल के बजाय एक वेब पेज खोला। Google Drive और Dropbox के लिए, फ़ाइल को "लिंक वाला कोई भी व्यक्ति" के साथ साझा करें और वह लिंक चिपकाएँ।','The link answered with HTTP %d.'=>'लिंक ने HTTP %d के साथ उत्तर दिया।','The file list could not be written.'=>'फ़ाइल सूची नहीं लिखी जा सकी।','The storage service could not be reached: %s'=>'स्टोरेज सेवा तक नहीं पहुँचा जा सका: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ने HTTP %2$d के साथ उत्तर दिया: %3$s','no details given'=>'कोई विवरण नहीं दिया गया','You are not allowed to manage backups.'=>'आपको बैकअप प्रबंधित करने की अनुमति नहीं है।','Tick the box to confirm that the restore replaces this site’s files and database.'=>'यह पुष्टि करने के लिए बॉक्स को चेक करें कि पुनर्स्थापना इस साइट की फ़ाइलों और डेटाबेस को बदल देगी।','Save the destination first.'=>'पहले गंतव्य सहेजें।','Connected: a test file was written and removed.'=>'कनेक्ट हो गया: एक परीक्षण फ़ाइल लिखी गई और हटा दी गई।','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'पहले अपने Dropbox ऐप की ऐप कुंजी दर्ज करें (फ़ॉर्म के बगल में दिए गए चरण देखें)।','This kind of storage does not sign in.'=>'इस प्रकार का स्टोरेज साइन इन नहीं करता है।','The sign-in expired. Press Connect again.'=>'साइन-इन की समय सीमा समाप्त हो गई है। कृपया पुनः कनेक्ट करें दबाएं।','Dropbox is connected.'=>'Dropbox कनेक्ट है।','Settings saved.'=>'सेटिंग्स सहेजी गईं।','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'एक अन्य बैकअप, पुनर्स्थापना या आयात चल रहा है। इसके समाप्त होने की प्रतीक्षा करें, या इसे रद्द करें।','The upload was not started properly. Start again.'=>'अपलोड ठीक से शुरू नहीं हुआ था। पुनः प्रारंभ करें।','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'टुकड़ा नहीं पहुँचा। आपका सर्वर अपलोड आकार को सीमित कर सकता है; पुनः प्रयास करें।','Tick the box to confirm that the import replaces this site’s content and database.'=>'यह पुष्टि करने के लिए बॉक्स को चिह्नित करें कि आयात इस साइट की सामग्री और डेटाबेस को बदल देगा।','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'आयात करने के लिए एक संग्रह चुनें: इसे अपलोड करें, एक लिंक पेस्ट करें, या आयात फ़ोल्डर से किसी एक को चुनें।','Hosting customer? Get %1$d%% off %2$s'=>'होस्टिंग ग्राहक हैं? %2$s पर %1$d%% की छूट प्राप्त करें','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Zinn Digital® होस्टिंग ग्राहक के रूप में आपको अपने पहले भुगतान पर %d%% की छूट के लिए एक व्यक्तिगत कोड मिलता है। नवीनीकरण सामान्य मूल्य पर होते हैं।','Get my %d%% code and go to checkout'=>'मेरा %d%% कोड प्राप्त करें और चेकआउट पर जाएं','Sorry, you are not allowed to do that.'=>'क्षमा करें, आपको ऐसा करने की अनुमति नहीं है।','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'यह छूट उन ग्राहकों के लिए है जिनके पास अच्छी स्थिति वाला सशुल्क होस्टिंग प्लान है। निःशुल्क परीक्षण इसके पात्र नहीं हैं।','You have already used your hosting-customer discount for this plugin.'=>'आप इस प्लगइन के लिए अपनी होस्टिंग-ग्राहक छूट का उपयोग पहले ही कर चुके हैं।','We could not get your code just now. Please try again in a few minutes.'=>'हम अभी आपका कोड प्राप्त नहीं कर सके। कृपया कुछ मिनटों में पुनः प्रयास करें।','Reading the backup'=>'बैकअप पढ़ा जा रहा है','Downloading the archive'=>'संग्रह डाउनलोड किया जा रहा है','Recognising the archive'=>'संग्रह को पहचाना जा रहा है','Restoring files'=>'फ़ाइलें पुनर्स्थापित की जा रही हैं','Downloading the database'=>'डेटाबेस डाउनलोड हो रहा है','Restoring the database'=>'डेटाबेस पुनर्स्थापित किया जा रहा है','Updating the site address'=>'साइट का पता अपडेट किया जा रहा है','Switching to the restored database'=>'पुनर्स्थापित डेटाबेस पर स्विच किया जा रहा है','The restore reached an unknown stage.'=>'पुनर्स्थापना एक अज्ञात चरण पर पहुंच गई।','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'इस फ़ोल्डर में कोई पूर्ण Zinn® Backups बैकअप नहीं है (मेनिफ़ेस्ट गायब है)।','This backup is encrypted. Enter its passphrase to restore it.'=>'यह बैकअप एन्क्रिप्टेड है। इसे पुनर्स्थापित करने के लिए इसका पासफ़्रेज़ दर्ज करें।','This incremental backup needs backup %s, which is no longer in the storage.'=>'इस वृद्धिशील बैकअप को बैकअप %s की आवश्यकता है, जो अब स्टोरेज में नहीं है।','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s का बैकअप पुनर्स्थापित किया जा रहा है (%2$d फ़ाइल भाग)।','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'%1$s फ़ाइल को अधिलेखित नहीं किया जा सका क्योंकि इस साइट को इसे बदलने की अनुमति नहीं है, और इसे वैसा ही छोड़ दिया गया जैसा यह था: %2$s' . "\0" . '%1$s फ़ाइलें अधिलेखित नहीं की जा सकीं क्योंकि इस साइट को उन्हें बदलने की अनुमति नहीं है, और उन्हें जैसा था वैसा ही छोड़ दिया गया: %2$s','Restored %s files.'=>'%s फ़ाइलें पुनर्स्थापित की गईं।','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'डाउनलोड करने के बाद %s अपने चेकसम से मेल नहीं खाता है। स्टोरेज में मौजूद कॉपी क्षतिग्रस्त हो सकती है।','%s did not arrive. Upload it again.'=>'%s नहीं आया। कृपया इसे फिर से अपलोड करें।','Recognised: %s.'=>'पहचाना गया: %s।','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'wp-content में %1$s फ़ाइलें आयात की गईं (%2$s छोड़ दी गईं: कैश, ड्रॉप-इन्स और अन्य बैकअप प्लगइन्स के फ़ोल्डर)।','The archive has no database dump, so only files were imported.'=>'अभिलेखागार (संग्रह) में कोई डेटाबेस डंप नहीं है, इसलिए केवल फ़ाइलें आयात की गईं।','Database restored into %d temporary tables.'=>'डेटाबेस को %d अस्थायी तालिकाओं में पुनर्स्थापित किया गया।','%s has no WordPress tables in it and was skipped.'=>'%s में कोई WordPress तालिकाएँ नहीं हैं और इसे छोड़ दिया गया था।','The backup’s database has no WordPress tables, so nothing was replaced.'=>'बैकअप के डेटाबेस में कोई WordPress तालिकाएँ नहीं हैं, इसलिए कुछ भी बदला नहीं गया।','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'यह बैकअप मल्टीसाइट नेटवर्क का है। किसी नेटवर्क को एकल साइट में पुनर्स्थापित करना समर्थित नहीं है।','Moving the content from %1$s to %2$s.'=>'सामग्री को %1$s से %2$s पर स्थानांतरित किया जा रहा है।','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'पुनर्स्थापना पूर्ण हुई। यदि आप साइन आउट हो गए हैं, तो पुनर्स्थापित साइट के किसी खाते से साइन इन करें।','Restore complete.'=>'पुनर्स्थापना पूर्ण हुई।','%1$s — trying again in %2$d seconds.'=>'%1$s — %2$d सेकंड में पुनः प्रयास किया जा रहा है।','Cancelled.'=>'रद्द किया गया।','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'बैकअप एक संग्रहण गंतव्य पर जाते हैं। किसी भिन्न का उपयोग करने के लिए आपके पास जो है उसे संपादित करें या हटाएं।','The database file could not be opened.'=>'डेटाबेस फ़ाइल खोली नहीं जा सकी।','The database refused a statement from the backup: %1$s (%2$s…)'=>'डेटाबेस ने बैकअप से एक स्टेटमेंट अस्वीकार कर दिया: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'पुनर्स्थापित तालिकाओं को बदला नहीं जा सका: %s। आपकी साइट अपरिवर्तित है।','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'अस्थायी बैकअप फ़ाइलों के लिए कोई लिखने योग्य फ़ोल्डर नहीं है। wp-content को लिखने योग्य बनाएं और पुनः प्रयास करें।','Could not create a folder for this job.'=>'इस कार्य के लिए फ़ोल्डर नहीं बनाया जा सका।','%s — guides and services'=>'%s — मार्गदर्शिकाएँ और सेवाएँ','User guides'=>'उपयोगकर्ता मार्गदर्शिकाएँ','Read the %s user guide'=>'%s उपयोगकर्ता गाइड पढ़ें','Hide this'=>'इसे छिपाएं','Zinn® hosting for WordPress'=>'WordPress के लिए Zinn® होस्टिंग','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक बैकअप, निःशुल्क माइग्रेशन और एक से अधिक साइट चलाने वाले लोगों के लिए बनाया गया एक नियंत्रण कक्ष।','The Zinn® marketplace'=>'Zinn® मार्केटप्लेस','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'स्थापित साइटें, डोमेन और लिंक प्लेसमेंट खरीदें और बेचें, जिसमें पैसा तब तक सुरक्षित रखा जाता है जब तक कि दोनों पक्ष संतुष्ट न हो जाएं।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — ऐसे लोगों को नियुक्त करें जो इसे पेशे के रूप में करते हैं','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हमारा वैश्विक फ्रीलांस मार्केटप्लेस: लेखकों, डिजाइनरों, डेवलपर्स और एसईओ विशेषज्ञों की 10,000 से अधिक तैयार सेवाओं को ब्राउज़ करें, या एक प्रोजेक्ट पोस्ट करें और उन्हें बोली लगाने दें।','See the Zinn Digital® release notes.'=>'Zinn Digital® रिलीज़ नोट्स देखें।','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अपडेट सेवा ने इस अपडेट के लिए डाउनलोड लिंक जारी नहीं किया। जांचें कि क्या यह साइट Zinn® प्लेटफ़ॉर्म तक पहुंच सकती है, फिर पुन: प्रयास करें।','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® अपडेट सेवा (%s) से अपडेट डाउनलोड नहीं किया जा सका। कृपया कुछ मिनटों बाद पुन: प्रयास करें।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड किया गया अपडेट अपनी अखंडता जांच में विफल रहा और इंस्टॉल नहीं किया गया।','The zip archive could not be opened. It may be damaged or incomplete.'=>'ज़िप संग्रह को खोला नहीं जा सका। यह क्षतिग्रस्त या अधूरा हो सकता है।','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'यह .wpress फ़ाइल ऐसे प्रारूप का उपयोग करती है जिसे हम पढ़ नहीं सकते (यह All-in-One WP Migration द्वारा संपीड़ित या एन्क्रिप्टेड हो सकती है)। कृपया इसे बिना एन्क्रिप्शन के पुनः निर्यात करें।','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'यह एक Duplicator “DupArchive” (.daf) फ़ाइल है। Duplicator में, संग्रह प्रारूप को ZIP पर सेट करके पैकेज को फिर से बनाएं, फिर उसे आयात करें।','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'यह UpdraftPlus डेटाबेस बैकअप एन्क्रिप्टेड है। इसे UpdraftPlus में डिक्रिप्ट करें (या डेटाबेस एन्क्रिप्शन बंद करके दोबारा बैकअप लें), फिर इसे आयात करें।','Database dump'=>'डेटाबेस डंप','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s कोई ऐसा बैकअप संग्रह नहीं है जिसे हम पढ़ सकें (zip, tar, tar.gz, .wpress, .sql या .sql.gz)।','Website archive'=>'वेबसाइट संग्रह','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s में कोई WordPress सामग्री नहीं है (कोई wp-content फ़ोल्डर नहीं और कोई डेटाबेस डंप नहीं)।','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'यह .wpress फ़ाइल All-in-One WP Migration द्वारा एन्क्रिप्ट या संपीड़ित है। कृपया एन्क्रिप्शन और संपीड़न को बंद करके इसे फिर से निर्यात करें, फिर उसे आयात करें।','Other S3-compatible storage'=>'अन्य S3-संगत स्टोरेज','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 या S3-संगत','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'इस साइट पर स्टोरेज कुंजियाँ पढ़ी नहीं जा सकीं। स्टोरेज टैब पर गुप्त कुंजी फिर से दर्ज करें।','This kind of storage is not known.'=>'इस प्रकार का स्टोरेज अज्ञात है।','Choose a kind of storage.'=>'संग्रहण का प्रकार चुनें।','Enter the bucket name and the access key.'=>'बकेट का नाम और एक्सेस कुंजी दर्ज करें।','Enter your Cloudflare account id (or the full R2 endpoint).'=>'अपना Cloudflare खाता आईडी (या पूरा R2 एंडपॉइंट) दर्ज करें।','Enter the endpoint address of your storage.'=>'अपने स्टोरेज का एंडपॉइंट पता दर्ज करें।','Enter the OAuth client id from your Google Cloud project.'=>'अपने Google Cloud प्रोजेक्ट से OAuth client id दर्ज करें।','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox ने रीफ्रेश टोकन नहीं लौटाया। कृपया कनेक्शन फिर से शुरू करें।','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox कनेक्ट नहीं है। इसे स्टोरेज टैब पर फिर से कनेक्ट करें।','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google ने रीफ्रेश टोकन वापस नहीं किया। इस साइट को अपने Google खाते के तृतीय-पक्ष एक्सेस से हटाएं और फिर से कनेक्ट करें।','That file is not in Google Drive any more.'=>'वह फ़ाइल अब Google Drive में नहीं है।','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive कनेक्ट नहीं है। स्टोरेज टैब पर इसे फिर से कनेक्ट करें।','The storage service did not start the upload.'=>'संग्रहण सेवा ने अपलोड प्रारंभ नहीं किया।','The storage service sent a reply that could not be read.'=>'स्टोरेज सेवा ने ऐसा उत्तर भेजा जिसे पढ़ा नहीं जा सका।','A temporary backup file could not be read.'=>'एक अस्थायी बैकअप फ़ाइल को पढ़ा नहीं जा सका।','A deploy link is read-only.'=>'डिप्लॉय लिंक केवल पढ़ने के लिए है।','The deploy code has no link for a file this backup needs.'=>'डिप्लॉय कोड में उस फ़ाइल के लिए कोई लिंक नहीं है जिसकी इस बैकअप को आवश्यकता है।','The deploy link'=>'डिप्लॉय लिंक']];